import {resolveImport, documentPath} from './imports.mjs';
export function model(doc){if(!doc||typeof doc!=='object'||Array.isArray(doc))throw Error('Expected an OSCAL JSON object.');const types=['catalog','profile'].filter(k=>doc[k]);if(types.length!==1)throw Error('Provide exactly one catalog or profile root.');if(typeof doc[types[0]]!=='object'||Array.isArray(doc[types[0]]))throw Error('OSCAL root must be an object.');return {type:types[0],body:doc[types[0]]}}
export function flatten(root){const out=[];function walk(n,groups=[],parents=[]){for(const g of n.groups||[])walk(g,[...groups,g],parents);for(const c of n.controls||[]){out.push({control:c,groups,parents});walk(c,groups,[...parents,c.id])}}walk(root);return out}
export function makeValidator(Ajv,schemas){const ajv=new Ajv({allErrors:true,strict:false});ajv.addFormat('uri',s=>{try{return !!new URL(s).protocol&&!/\s/.test(s)}catch{return false}});ajv.addFormat('uri-reference',s=>{try{new URL(s,'https://example.org/');return !/[\s<>]/.test(s)}catch{return false}});ajv.addFormat('email',/^[^\s@]+@[^\s@]+\.[^\s@]+$/);ajv.addFormat('date-time',s=>/^\d{4}-\d\d-\d\d[Tt]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)$/.test(s)&&!Number.isNaN(Date.parse(s)));const validators=Object.fromEntries(Object.entries(schemas).map(([k,s])=>[k,ajv.compile(s)]));return doc=>{let m;try{m=model(doc)}catch(e){return [{severity:'error',path:'/',message:e.message}]}const v=validators[m.type];v(doc);const issues=(v.errors||[]).map(e=>({severity:'error',path:e.instancePath||'/',message:e.message+(e.params?.missingProperty?' ('+e.params.missingProperty+')':'')}));if(m.body.metadata?.['oscal-version']!=='1.0.4')issues.unshift({severity:'warning',path:'/metadata/oscal-version',message:'Bundled schema is OSCAL 1.0.4. This document’s declared version is not supported for conformance validation.'});const seen=new Map();function walk(x,path=''){if(!x||typeof x!=='object')return;for(const [k,v]of Object.entries(x)){const p=path+'/'+k;if(Array.isArray(v)){for(let i=0;i<v.length;i++){const item=v[i];const id=item?.id||item?.uuid;if(id&&['controls','groups','params','parts','resources','parties','roles','locations'].includes(k)){const key=k+':'+id;if(seen.has(key))issues.push({severity:'error',path:p+'/'+i,message:'Duplicate '+k+' identifier: '+id});seen.set(key,true)}walk(item,p+'/'+i)}}else if(v&&typeof v==='object')walk(v,p)}}walk(m.body);return issues}}
const clone=x=>JSON.parse(JSON.stringify(x));
function matches(row,selectors=[]){return selectors.some(s=>{const ids=s['with-ids']||[];const patterns=(s.matching||[]).map(m=>new RegExp('^'+m.pattern.split('*').map(p=>p.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('.*')+'$'));const hit=id=>ids.includes(id)||patterns.some(p=>p.test(id));return hit(row.control.id)||(s['with-child-controls']==='yes'&&row.parents.some(hit))})}
export function preview(doc,documents,trail=[]){const {type,body}=model(doc);if(type==='catalog')return {rows:flatten(body),sources:[body],notes:[]};if(trail.includes(doc))throw Error('Circular profile import detected.');const rows=[],sources=[],notes=[];for(const imp of body.imports||[]){const source=documents.find(d=>d.doc===doc)||{name:'profile.json'};const target=resolveImport(body,imp.href,source,documents);const imported=preview(target.doc,documents,[...trail,doc]);sources.push(...imported.sources);notes.push(...imported.notes);for(const selector of [...(imp['include-controls']||[]),...(imp['exclude-controls']||[])])for(const id of selector['with-ids']||[])if(!imported.rows.some(r=>r.control.id===id))throw Error('Unknown selected control: '+id);const selected=imported.rows.filter(r=>('include-all'in imp||matches(r,imp['include-controls']))&&!matches(r,imp['exclude-controls']));rows.push(...selected.map(r=>({...r,control:clone(r.control),source:documentPath(target)})));}
const duplicates=rows.filter((r,i)=>rows.findIndex(x=>x.control.id===r.control.id)!==i);if(duplicates.length)notes.push('Duplicate controls across imports: '+[...new Set(duplicates.map(r=>r.control.id))].join(', ')+'. Combine behaviour is not applied.');if(body.merge?.custom)notes.push('Custom group ordering is not applied. Source groups are shown.');if(body.merge?.combine)notes.push('Merge combine directives are not applied.');if(body.merge?.['as-is']===false||body.merge?.flat)notes.push('Source grouping is retained for this selection preview.');if(body.modify?.alters?.length)notes.push('Control alterations are not applied. Read the profile source for these directives.');for(const setting of body.modify?.['set-parameters']||[]){let found=false;for(const row of rows){for(const p of row.control.params||[])if(p.id===setting['param-id']){Object.assign(p,clone(setting));delete p['param-id'];found=true}}if(!found)notes.push('Parameter '+setting['param-id']+' is outside selected control parameters; its setting is not applied.');}return {rows,sources,notes:[...new Set(notes)]}}
